    const uint64_t product = (uint64_t)duration_us * frequency_hz;
    const uint64_t value = product / 1000000 + (product % 1000000 != 0);
    if (value > UINT32_MAX) {
        return MATH_OVERFLOW;
    }
    *ticks = (uint32_t)value;
    return MATH_OK;
}

